import React from 'react';

const ChatButton = ({ onClick }) => (
  <button
    onClick={onClick}
    className="flex items-center gap-2 bg-blue-600 text-white px-3 py-2 rounded-full shadow-lg animate-pulse hover:animate-none"
    style={{ animation: 'glow 2s ease-in-out infinite' }}
  >
    <span className="text-xl">💬</span>
    <span>Community</span>
  </button>
);

export default ChatButton;
